INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("迷宮内部で発⾒された腕輪の遺物\nあしらわれた蒼珠が、敵を感知し\n力を授ける。", 2, "蒼珠の腕輪", 0, 21003, 2, 21003, 10, 2800, "バトル開始時ＴＰ200回復", 1);
