INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("迷宮内部で発⾒された、⼑の遺物\n血で⾚く染まった⼑⾝で、敵の装\n甲をたやすく断ち割る。", 2, "斬赤刃ディバイド", 0, 22005, 2, 22005, 10, 2800, "敵の物理/魔法防御力－20％", 2);
