INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("迷宮内部で発⾒された、鎧の遺物\n紅き鋼の加護は、守備力を攻撃力\nへと変換する力を持つ。", 2, "紅反鋼のアーマー", 0, 24002, 2, 24002, 10, 2800, "物理/魔法攻撃力アップ\n（先頭キャラの物理防御力×10）", 4);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("迷宮内部で発⾒された、ドレスの\n遺物。精霊の加護が、防魔結界か\nら力を集めてくれる。", 2, "聖減術のテラドレス", 0, 24003, 2, 24003, 10, 2800, "物理/魔法攻撃力アップ\n（先頭キャラの魔法防御力×10）", 4);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("迷宮内部で発見された、大剣の形\nをした遺物。湧き出る炎の力が、\n攻撃の能力を大きく高める。", 2, "炎王のグレートソード", 0, 24004, 2, 24004, 10, 2800, "物理/魔法攻撃力＋40％", 4);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("迷宮内部で発⾒された鎧の遺物。\n千年咲く桜の如く、盤石な堅牢さ\nを装備者に与える。", 2, "桜堅牢のコート", 0, 24005, 2, 24005, 10, 2800, "物理/魔法防御力＋20％", 4);
