INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("迷宮内部で発見された、指輪の形\nをした遺物。装備者を天空の護り\nで包み込み生命力を増幅させる。", 2, "空命護珠", 0, 25002, 2, 25002, 10, 2800, "ＨＰ＋20％", 5);
