INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("迷宮内部で発⾒された、ローブの\n遺物。神樹の蔦が織り込まれ、装\n備者を魔法から護る。", 2, "魔護霊装", 0, 25004, 2, 25004, 10, 2800, "15秒ごとに魔法無効バリア展開（【守備】数×1000無効）", 5);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("迷宮内部で発⾒された、腕輪の遺\n物。溢れ出す⾃然の⼒は装備者に\n生命の息吹をもたらす。", 2, "緑護ノ盾輪", 0, 25005, 2, 25005, 10, 2800, "継続ＨＰ回復（毎秒【守備】数×1000回復）", 5);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("迷宮中枢部に隠された黎明の秘宝\nデータ保管のため属性の⼒の断⽚\nが封じられており、内なるアスト\nラルを著しく上昇させる。", 0, "エレメントサージオーブ", 0, 30001, 3, 30001, 10, 3800, "属性ボーナス＋100％", 0);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("迷宮の奥深くに眠っていた月を象\nる耳飾り。内部から発する魔力は\n装備者に蝶のような瞬麗さを授け\n活力加速を大きく上昇させる。", 3, "瞬閃蝶の月飾り", 0, 31001, 3, 31001, 10, 3800, "ＴＰ上昇＋15", 1);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("迷宮の奥深くに眠る宝石を飾った\n円盾。海のような青き魔力は装備\n者に庇護を与え、迫り来る脅威す\nらエネルギーへと昇華させる。", 3, "海宝華の煌盾", 0, 31002, 3, 31002, 10, 3800, "ダメージを受けるたびＴＰ100回復（最大３回）", 1);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("迷宮の奥深くに眠る聖なる腕輪。\n失われた技術で装飾された宝石が\n装備者に加護を齎し、危機が迫る\nと膨大な力を分け与える。", 3, "碧貴石の聖輪", 0, 31003, 3, 31003, 10, 3800, "バトル開始時ＴＰ300回復", 1);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("迷宮の奥深くに眠る、かつて天界\nに伝えられし杖。天にかざすと鏡\n⽟に篭められた祈りが溢れ出して\n尽きることなき力を授ける。", 3, "永天鏡の王笏", 0, 31004, 3, 31004, 10, 3800, "ＴＰ消費軽減＋6", 1);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("迷宮の奥深くに眠る、天使の加護\nを宿した戦靴。装備するだけで神\n性を授かり、天使のような自在さ\nで空を翔ることができる。", 3, "熾天使の翔靴", 0, 31005, 3, 31005, 10, 3800, "重複可能の行動速度＋30％", 1);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("迷宮最奥部に鎮祀されし神業の遺\n物。風を司る神々の恩寵が宿され\nており、装備者は無尽蔵の活力が\n疾風の如き速さで体を駆け巡る。", 5, "風神の護風恩寵", 0, 31006, 3, 31006, 10, 9999, "ＴＰ上昇＋100", 1);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("迷宮の奥深くに眠る、幻獣を象る\n首飾り。この宝石の神秘に魅せら\nれた者は、一切の異変や脅威に抗\nうことができなくなってしまう。", 3, "幻獣飾テンタシオン", 0, 32001, 3, 32001, 10, 3800, "状態異常命中＋60", 2);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("迷宮の奥深くに眠る、月を蝕む杖\n存在するだけで、絶えず呪力の奔\n流を溢れさせ、近づく全ての敵を\n呪いで浸食していく。", 3, "深淵蝕杖マリディクト", 1, 32002, 3, 32002, 10, 3800, "敵全体に呪い付与（毎秒【弱体】数×1500ダメージ）", 2);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("迷宮の奥深くに眠る、黒刃の刺剣\n刃に埋め込まれた宝玉が、絶え間\nなく邪毒を撒き散らし、破滅へと\n刻々と時を数える。", 3, "滅刻凶刃ヴェノマス", 0, 32003, 3, 32003, 10, 3800, "敵全体に毒付与（毎秒【弱体】数×1500ダメージ）", 2);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("迷宮の奥深くに眠る、宝飾をあし\nらったベール。蔽布の下から滲み\n出るオーラが、相手の敵意を解き\nほぐし、無力化させてしまう。", 3, "燦然御纏アノラ・ベイラ", 0, 32004, 3, 32004, 10, 3800, "敵の物理/魔法攻撃力－30％", 2);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("迷宮の奥深くに眠る、⼑⾝に鎖を\n這わせた妖⼑。主の意思に逆らい\n暴れる鎖が怨敵の守りを打ち崩し\n紫黒の凶刃が悉くを断ち斬る。", 3, "断壁鎖刃フラグメント", 0, 32005, 3, 32005, 10, 3800, "敵の物理/魔法防御力－30％", 2);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("迷宮深層部に静眠せし虚影の装衣\n深淵から出でし蝕影は、存在全て\nを霜雪の如く凍てつかせ、抗う敵\nの剣盾両翼を虚壊させる。", 5, "霜影虚装アビスモナーク", 0, 32006, 3, 32006, 10, 9999, "敵の物理/魔法与ダメ－25％\n敵の物理/魔法被ダメ＋25％", 2);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("迷宮の奥深くに眠る、地神の力を\n宿した烈槍。大地の力を糧に放つ\n無比の一閃は、地に立つすべての\n敵に甚大なダメージを与える。", 3, "リーサルハルバード", 0, 33001, 3, 33001, 10, 3800, "敵の物理/魔法被クリダメ＋30％", 3);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("迷宮の奥深くに眠る、伝説に語ら\nれる極みの一振り。鳳凰の力を宿\nした真紅の刃は、焔の如き赫く激\n烈な一撃を与える。", 3, "オオトリノカタナ", 0, 33002, 3, 33002, 10, 3800, "物理/魔法クリダメ＋30％", 3);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("迷宮の奥深くに眠る、地核のエネ\nルギーを封じた籠手。振るう一撃\nは、世界を破壊するかの如く、通\n常攻撃を大きく強化する。", 3, "アースデストラクション", 0, 33003, 3, 33003, 10, 3800, "通常攻撃強化＋90", 3);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("迷宮の奥深くに眠る、咎⼈を裁き\nし聖⼸。この弓に選ばれし装備者\nは神⾵の加護を得て、対象に慈悲\nを与えず一瞬で急所を射貫く。", 3, "ジャッジメントアロー", 0, 33004, 3, 33004, 10, 3800, "物理/魔法クリティカル＋30％", 3);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("迷宮の奥深くに眠る、金色の⼤戦\n斧。刈り取った獲物の魂を糧に、\nその絢爛なる刃は燦燦と輝きを増\nしてゆく。", 3, "ザ・ハーヴェスト", 0, 33005, 3, 33005, 10, 3800, "ＨＰ吸収＋30", 3);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("迷宮最深部に残された久遠の遺物\n神代の大戦より聖騎士に脈々と受\nけ継がれ、装備者へ戦いの記憶と\nともに不滅の力を分け与える。", 5, "セレスティアルエイジ", 0, 33006, 3, 33006, 10, 9999, "通常攻撃強化＋500\nＨＰ吸収＋50", 3);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("迷宮の奥深くに眠る、炎天の魔力\nを封じた耳飾り。潜在能力を究極\nまで呼び覚まし、強化の力を大幅\nに上昇させる。", 3, "極醒のアミュレット", 0, 34001, 3, 34001, 10, 3800, "バフ強化＋90", 4);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("迷宮の奥深くに眠る、⽩⾦の鎧。\n⽩⻯の鱗を繋ぎ合わせた外装が盟\n友の力を集結させる効果を持ち強\n力無比な一撃を可能にする。", 3, "断刃拒絶のアルギュロス", 0, 34002, 3, 34002, 10, 3800, "物理/魔法攻撃力アップ\n（先頭キャラの物理防御力×15）", 4);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("迷宮の奥深くに眠る、栄華の象徴\nとして仕立てられたドレス。深紅\nに咲き乱れる花の加護は、装備者\nの絶魔の⼒を攻撃⼒へ変換する。", 3, "緋華栄華のグラナート", 0, 34003, 3, 34003, 10, 3800, "物理/魔法攻撃力アップ\n（先頭キャラの魔法防御力×15）", 4);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("迷宮の奥深くに眠る、光⿓の⼒を\n授かりし⼤剣。その⼀振りはかつ\nての栄光の羽ばたきを想起させ、\n極限の覇気を世界に放つ。", 3, "覇光帝龍のグローリア", 0, 34004, 3, 34004, 10, 3800, "物理/魔法攻撃力＋60％", 4);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("迷宮の奥深くに眠る、東の国に伝\nわりし聖鎧。玉の様に透き通る輝\nきを放つ鎧は、装備者に華の加護\nを授け、守護の力を高める。", 3, "華舞玲瓏のハルナデシコ", 0, 34005, 3, 34005, 10, 3800, "物理/魔法防御力＋30％", 4);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("迷宮深淵部に佇む歴戦無敗の⼤剣\n台座から剣を⼿にした者は天その\nものを冠すかの如き全能感を得て\n千軍を容易く退ける剛⼒を得る。", 5, "天戴冠のゼニスブレード", 0, 34006, 3, 34006, 10, 9999, "バトル開始時、物理/魔法攻撃力アップフィールド展開\n（現在値＋50％）", 4);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("迷宮の奥深くに眠る、妖精の輝き\nを封じた杖。宝⽟から無限の⽣命\n⼒が溢れ出し、増幅された快癒の\n⼒であらゆる苦しみを取り除く。", 3, "妖精霊杖・癒光", 0, 35001, 3, 35001, 10, 3800, "回復強化＋30", 5);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("迷宮の奥深くに眠る、翠緑に彩ら\nれた指輪。装備者に、かつて豊穣\nに溢れた楽園の光景を想起させ、\n際限なき⽣命⼒を与える。", 3, "泉湧命環・豊穣", 0, 35002, 3, 35002, 10, 3800, "ＨＰ＋30％", 5);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("迷宮の奥深くに眠る、白金の輝き\nを放つ鎧。顕現する翅は、意思を\n持つかのよう、装備者に呼応して\n物理攻撃を断つ障壁を展開する。", 3, "白光輝鎧・断壁", 0, 35003, 3, 35003, 10, 3800, "15秒ごとに物理無効バリア展開（【守備】数×1500無効）", 5);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("迷宮の奥深くに眠る、幽庵の煌き\nを宿す鎧。顕現する翅は、意思を\n持つかのよう、装備者に呼応して\n魔法攻撃を絶つ障壁を展開する。", 3, "幽玄煌装・絶魔", 0, 35004, 3, 35004, 10, 3800, "15秒ごとに魔法無効バリア展開（【守備】数×1500無効）", 5);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("迷宮の奥深くに眠る、翠宝玉をあ\nしらった腕輪。常に滾々とマナが\n湧き出し、生命力を湛え続ける。", 3, "輪廻ノ翡翠珠輪", 0, 35005, 3, 35005, 10, 3800, "継続ＨＰ回復（毎秒【守備】数×1500回復）", 5);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("迷宮最下層に供奉された伝承の環\n選ばれし者がひとたび⼿にすれば\n創造神話の如く、千万無量の⽣命\n⼒を齎すと云われる。", 5, "天命授環・伊邪那", 0, 35006, 3, 35006, 10, 9999, "ＨＰ＋100％", 5);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("【美⾷殿】と共に迷宮を冒険する\nための遺物。王家の装備を精巧に\n模しており、味方の⾝体能⼒を⼤\nきく向上させてくれる。", 1, "プリンセスフォース", 0, 40001, 3, 40001, 10, 3200, "ＨＰ＋15％\n物理/魔法与ダメ＋15％", 5);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("【トゥインクルウィッシュ】と共\nに迷宮を冒険するための遺物。\n３人のアストラルに呼応して、属\n性の力を増幅させてくれる。", 1, "アストラルブースト", 0, 40002, 3, 40002, 10, 3200, "属性ボーナス＋50％", 4);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("【サレンディア救護院】と共に迷\n宮を冒険するための遺物。主人が\n築いた信頼関係のおかげで、商品\nの価格を値引きしてもらえる。", 1, "サレンディアエンゲージ", 0, 40003, 3, 40003, 10, 3200, "ショップの販売価格－10％", 1);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("【王宮騎士団】と共に迷宮を冒険\nするための遺物。団長の愛⽤品を\n模し会⼼率と引き換えに、会⼼時\nの威⼒を⾼めてくれる。", 1, "ナイツオブフェイス", 0, 40004, 3, 40004, 10, 3200, "物理/魔法クリダメ＋50％\n物理/魔法クリティカル－25％", 3);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("【ラビリンス】と共に迷宮を冒険\nするための遺物。迷宮女王はその\n権能でナイトがどこに居ようとも\n即座に参戦してくれる。", 1, "ラビリンスオーソリティ", 0, 40005, 3, 40005, 10, 3200, "挑戦開始時にラビリスタが加入", 2);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("【カルミナ】と共に迷宮を冒険す\nるための遺物。これを振るう者の\n熱き声援は、ステージに立つ者の\n能力をより一層高めてくれる。", 1, "イルミネイトカルミナ", 0, 40006, 3, 40006, 10, 3200, "物理/魔法攻撃力＋15％\nバフ強化＋15", 4);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("【悪魔偽王国軍】と共に迷宮を冒\n険するための遺物。紅き両刃から\n禍々しく迸る魔力の前では、いか\nなる敵だろうと戦意を失う。", 1, "ブルートナハト", 0, 40007, 3, 40007, 10, 3200, "敵のＴＰ上昇－15", 1);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("【牧場】と共に迷宮を冒険するた\nめの遺物。被ったらたちまちその\n場で最も目立つ存在となり、すべ\nての攻撃を引きつけてしまう。", 1, "エリザベスガーディアン", 0, 40008, 3, 40008, 10, 3200, "バトル開始時に最もＨＰが多いキャラが敵を挑発", 5);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("【メルクリウス財団】と共に迷宮\nを冒険するための遺物。人から決\nして多く受け取らず、生まれ持っ\nた財のみで戦いぬく高潔さの証。", 1, "ノブレスウィスタリア", 0, 40009, 3, 40009, 10, 3200, "初期アルファルピ+3000\nアルファルピ獲得量－10%", 3);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("【トワイライトキャラバン】と共\nに迷宮を冒険するための遺物。二\n本の刀が見せる煌めきは、悪党ど\nもの気炎を容易く挫く。", 1, "兵法二海一流", 0, 40010, 3, 40010, 10, 3200, "デバフ強化＋20", 2);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("【リトルリリカル】と共に迷宮を\n冒険するための遺物。中に宿って\nいる強い絆が、どこにいても３人\nをふたたび繋いでくれる。", 1, "絆のリボン", 0, 40011, 3, 40011, 10, 3200, "挑戦開始時にミソギ＆ミミ＆キョウカが加入", 3);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("【自警団】と共に迷宮を冒険する\nための遺物。護りの奥義が記され\nており、読み込めば攻撃から身を\n守る技術を得ることができる。", 1, "琉球犬甲唄", 0, 40012, 3, 40012, 10, 3200, "バトル開始時に先頭キャラに物理/魔法防御力+50%", 4);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("【フォレスティエ】と共に迷宮を\n冒険するための遺物。森の息吹を\n内に秘め、所持しているだけで味\n方に調和の力を授ける。", 1, "フォレストハーモニー", 0, 40013, 3, 40013, 10, 3200, "バトル開始時に調和状態", 5);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("【ルーセント学院】と共に迷宮を\n冒険するための遺物。誘惑した相\n手の生気を少しずつ削ぎ、気付か\nぬ間に甘い終焉を迎えさせる。", 1, "チャームファタール", 0, 40014, 3, 40014, 10, 3200, "1秒ごとに誘惑状態の敵に最大ＨＰの5％の魔法割合ダメージ（最大50万ダメージ）", 2);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("【美⾷殿】と共に迷宮を冒険する\nための遺物。冒険の道中で絆を結\nべば結ぶほどに、味⽅の攻撃⼒を\n⾼めてくれる。", 1, "プリンセスエンチャント", 0, 50001, 3, 50001, 10, 3200, "物理/魔法攻撃力アップ（加入キャラ数×4％、最大100％）", 4);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("【トゥインクルウィッシュ】と共\nに迷宮を冒険するための遺物。ギ\nルドマスターの諦めない心が、味\n方を一度だけ敗北から守る。", 1, "トゥインクルブレス", 1, 50002, 3, 50002, 10, 3200, "ボスバトルを除いて一度だけバトル敗北を免除", 5);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("【サレンディア救護院】と共に迷\n宮を冒険するための遺物。主人の\n気品を漂わせる剣は、築いた富を\n⼒に変転させる効果を持つ。", 1, "サレンディアノーブル", 0, 50003, 3, 50003, 10, 3200, "通常攻撃強化アップ（アルファルピ所持数×0.01、最大100）", 3);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("【王宮騎士団】と共に迷宮を冒険\nするための遺物。副団長の催す闘\n争の宴は、敵味⽅が受けるダメー\nジをみな悉く増加させる。", 1, "レジーナガーラ", 0, 50004, 3, 50004, 10, 3200, "敵の物理/魔法被ダメ＋25％\n味方の物理/魔法被ダメ＋25％", 2);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("【ラビリンス】と共に迷宮を冒険\nするための遺物。マスターの⼒を\n冠した剣は、開発者権限の⼀部を\n解放し、遺物を即座に獲得する。", 1, "マスターオブラビリンス", 0, 50005, 3, 50005, 10, 3200, "挑戦開始時にランダムな★1の迷宮遺物を１個獲得", 1);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("【カルミナ】と共に迷宮を冒険す\nるための遺物。ハンドマイクを通\nじて拡がっていく歌声は、味方の\n疲労をふき飛ばす。", 1, "ヴォイスフォーユー", 0, 50006, 3, 50006, 10, 3200, "30秒ごとに物理/魔法攻撃力ダウン解除", 4);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("【悪魔偽王国軍】と共に迷宮を冒\n険するための遺物。重く振りかざ\nす一撃は、斬り裂いた獲物の生気\nを我が物とする。", 1, "ディアボロスフィアー", 0, 50007, 3, 50007, 10, 3200, "15秒ごとにＴＰ固定量100回復\n敵のＴＰ100ダウン", 1);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("【牧場】と共に迷宮を冒険するた\nめの遺物。持ち主のやる気を呼び\n起こし、ぐうたらさを１回だけ無\n効化できる。あくまで１回だけ。", 1, "ドングリースピリット", 0, 50008, 3, 50008, 10, 3200, "行動不能無効１回", 5);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("【メルクリウス財団】と共に迷宮\nを冒険するための遺物。富を積め\nば積むほど精神を集中させ、必殺\nの一突きを敵に見舞う。", 1, "リヴァイアサンコール", 0, 50009, 3, 50009, 10, 3200, "物理/魔法クリダメアップ（アルファルピ所持数×0.01%、最大100%）", 3);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("【トワイライトキャラバン】と共\nに迷宮を冒険するための遺物。さ\nまざまな者たちの個性を学習し、\n敵を苦しめる術に転化する。", 1, "バインディングローズ", 0, 50010, 3, 50010, 10, 3200, "敵への継続ダメージアップ（加入キャラ数×10％、最大50万ダメージ）", 2);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("【リトルリリカル】と共に迷宮を\n冒険するための遺物。履くと元気\nが溢れ出し、走り回ってより多く\nの仲間を勧誘できる。", 0, "トリックランナー", 1, 50011, 3, 50011, 10, 3200, "コネクトサインマスの抽選回数+1（1回）", 0);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("【自警団】と共に迷宮を冒険する\nための遺物。姫さま親衛隊の精鋭\n隊員たちで、仲間をより増やすた\nめに日夜勤しんでいる。", 0, "姫さま親衛隊勧誘係", 3, 50012, 3, 50012, 10, 3200, "バトル勝利後時の仲間キャラ加入数+1（3回）", 0);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("【フォレスティエ】と共に迷宮を\n冒険するための遺物。きらりと輝\nく流れ星が、多くのアイテムを手\nに入れる幸運を呼び寄せる。", 0, "フォーチュンミーティア", 1, 50013, 3, 50013, 10, 3200, "迷宮遺物マスの抽選回数+1（1回）", 0);
INSERT INTO `v1_cf4d232dd6236ddd9dcc1c664f0232d536475e0bf8258b0aac2bf5771fb6f449` VALUES ("【ルーセント学院】と共に迷宮を\n冒険するための遺物。悪魔的なほ\nどに真紅の艶めきは、見た者の目\nを釘付けにし、二度と逃さない。", 0, "ベルベットルージュ", 1, 50014, 3, 50014, 10, 3200, "敵の誘惑時間+50％", 0);
